SELECT CAST(ROUND(
  MAX(C.POPULATION * 1.0 / CO.SURFACEAREA) - MIN(C.POPULATION * 1.0 / CO.SURFACEAREA)
) AS INTEGER)
FROM CITY C
JOIN COUNTRY CO ON C.COUNTRYCODE = CO.CODE
WHERE CO.CONTINENT = 'Asia';

SELECT CEIL(AVG(SALARY)) - CEIL(AVG(CAST(REPLACE(CAST(SALARY AS TEXT), '0', '') AS REAL)))
FROM EMPLOYEES
WHERE REPLACE(CAST(SALARY AS TEXT), '0', '') <> '';

SELECT ROUND(
  (SELECT LAT_N FROM STATION WHERE LAT_N > 0 ORDER BY LAT_N LIMIT 1 OFFSET (SELECT (COUNT(*) - 1) / 2 FROM STATION WHERE LAT_N > 0)),
  4
);

